(7472573, 1186679, 63398, '<td valign="top">From which the journey both begins and ends....<br/> <br/>Hope springs, accomplishment sings,<br/> <br/>A new day, a new way, and the future is upon you....</td>', 'From which the journey both begins and ends.... Hope springs, accomplishment sings, A new day, a new way, and the future is upon you....', '2016-09-05 23:06:09.000000', NULL, 1),
(7472575, 1186636, 63398, '<td valign="top">To the unbroken still surface he rises.....<br/> <br/>With naught but the errant leaf for company....<br/> <br/>The master of the depths emerges.</td>', 'To the unbroken still surface he rises..... With naught but the errant leaf for company.... The master of the depths emerges.', '2016-09-05 23:07:39.000000', NULL, 1),
(7472577, 1186159, 63398, '<td valign="top">Though the sea beckons in its vastness...<br/> <br/>The lowly spit of sand offers an anchorage....<br/> <br/>And the wonder of where it leads is unanswered.</td>', 'Though the sea beckons in its vastness... The lowly spit of sand offers an anchorage.... And the wonder of where it leads is unanswered.', '2016-09-05 23:08:43.000000', NULL, 1),
(7472579, 1186934, 63398, '<td valign="top">Through the innocence of a child....<br/> <br/>Peace and harmony overcome the brutality of a hostile world.....<br/> <br/>Offering a much needed respite from the mayhem.</td>', 'Through the innocence of a child.... Peace and harmony overcome the brutality of a hostile world..... Offering a much needed respite from the mayhem.', '2016-09-05 23:10:03.000000', NULL, 1),
(7472582, 1186713, 63398, '<td valign="top">Feel me, touch me, heal me.....<br/> <br/>Though I am but an insignificant being.....<br/> <br/>I exist on this mortal coil with you....<br/> <br/>If I can, you can too....</td>', 'Feel me, touch me, heal me..... Though I am but an insignificant being..... I exist on this mortal coil with you.... If I can, you can too....', '2016-09-05 23:12:25.000000', NULL, 1),
(7472584, 1186320, 63398, '<td valign="top">The cacophony of the warmup.....<br/> <br/>The chaos before the he reins them all in....<br/> <br/>To create that rare blend of life and art.</td>', 'The cacophony of the warmup..... The chaos before the he reins them all in.... To create that rare blend of life and art.', '2016-09-05 23:13:22.000000', NULL, 1),
(7472585, 1186940, 63398, '<td valign="top">Amongst many, but alone....<br/> <br/>Traveling through space and time.....<br/> <br/>In search of the true one for him.</td>', 'Amongst many, but alone.... Traveling through space and time..... In search of the true one for him.', '2016-09-05 23:14:09.000000', NULL, 1),
(7472587, 1186119, 63398, '<td valign="top">Into the sky, back to the earth.....<br/> <br/>Twisting, turning, fast the slow.....<br/> <br/>Where will you be when it ends????</td>', 'Into the sky, back to the earth..... Twisting, turning, fast the slow..... Where will you be when it ends????', '2016-09-05 23:15:03.000000', NULL, 1),
(7472588, 1186593, 63398, '<td valign="top">Cook, butler, laundress, nurse.....<br/> <br/>Travel agent, guide, teacher, savior....<br/> <br/>But most of all, protector of the ones she loves....</td>', 'Cook, butler, laundress, nurse..... Travel agent, guide, teacher, savior.... But most of all, protector of the ones she loves....', '2016-09-05 23:16:13.000000', NULL, 1),
(7472590, 1186756, 63398, '<td valign="top">Poised on the brink of adventure....<br/> <br/>Unsure what the horizon holds....<br/> <br/>Whether or not the voyage is imminent....<br/> <br/>Only the spirit knows for sure.</td>', 'Poised on the brink of adventure.... Unsure what the horizon holds.... Whether or not the voyage is imminent.... Only the spirit knows for sure.', '2016-09-05 23:17:27.000000', NULL, 1),
(7472591, 1186839, 63398, '<td valign="top">When the depths seem uncertain.....<br/> <br/>When the past is gone in its vengeance....<br/> <br/>World-weary and brutalized....<br/> <br/>The light is your last and only hope....<br/> <br/>Despair not.</td>', 'When the depths seem uncertain..... When the past is gone in its vengeance.... World-weary and brutalized.... The light is your last and only hope.... Despair not.', '2016-09-05 23:19:45.000000', NULL, 1),
(7472593, 1186961, 63398, '<td valign="top">Though the lightning rips the sky....<br/> <br/>Thunder crashes with deafening resonance....<br/> <br/>The water spills from the sky unabated....<br/> <br/>Life is rejuvenated with its cleansing.</td>', 'Though the lightning rips the sky.... Thunder crashes with deafening resonance.... The water spills from the sky unabated.... Life is rejuvenated with its cleansing.', '2016-09-05 23:21:07.000000', NULL, 1),
(7472600, 1186775, 63398, '<td valign="top">Though life did not take the course imagined....<br/> <br/>Though circumstances as now were not forseen...<br/> <br/>There is still joy and purpose deapie where we are...<br/> <br/>Hope springs eternal.</td>', 'Though life did not take the course imagined.... Though circumstances as now were not forseen... There is still joy and purpose deapie where we are... Hope springs eternal.', '2016-09-05 23:25:27.000000', NULL, 1),
(7472601, 1186261, 63398, '<td valign="top">Though towering high above the horizon....<br/> <br/>Its life so lonely in its majesty....<br/> <br/>Its beauty and islolation a curse unto itself.</td>', 'Though towering high above the horizon.... Its life so lonely in its majesty.... Its beauty and islolation a curse unto itself.', '2016-09-05 23:26:55.000000', NULL, 1),
(7472605, 1186960, 63398, '<td valign="top">Remember when life was simple and innocent...<br/> <br/>If only it did not have to succumb to reality....<br/> <br/>And the angst of not being able to save them from it.</td>', 'Remember when life was simple and innocent... If only it did not have to succumb to reality.... And the angst of not being able to save them from it.', '2016-09-05 23:28:09.000000', NULL, 1),
